def get_calibration(R_s, C, eps):
    """
    Only explicitly validated (R_s,C,epsilon) calibrations are supported.
    """
    key = (float(R_s), float(C), float(eps))
    if key not in NFW_CALIBRATIONS:
        raise ValueError(f"No validated NFW surrogate calibration for R_s={R_s}, C={C}, eps={eps}. Valid keys: {list(NFW_CALIBRATIONS.keys())}")
    return NFW_CALIBRATIONS[key]